private Rectangle CreatePhysicalSelectionRectangle(Rect selectionDip)
{
    Matrix t = PresentationSource.FromVisual(this).CompositionTarget.TransformToDevice;
    double left = selectionDip.Left * t.M11;
    double right = selectionDip.Right * t.M11;
    if (RegionClickCanvas.FlowDirection == FlowDirection.RightToLeft || FlowDirection == FlowDirection.RightToLeft)
    {
        (left, right) = (screenRectangle.Width - right, screenRectangle.Width - left);
    }
    return Rectangle.FromLTRB((int)Math.Round(left), (int)Math.Round(selectionDip.Top * t.M22), (int)Math.Round(right), (int)Math.Round(selectionDip.Bottom * t.M22));
}

